    {
      "ordinal": 2,
      "summary": "用甲骨文写信的人死于一九八○年代最后的那个夏天；二十多年前那次没有仪式的生命告别，从灵魂放飞、孤灯守灵到扶棺下葬、清明立碑，曾本之从头到尾都在现场。",
      "chronology": "二十多年前（一九八○年代最后一个夏天）",
      "participants": ["曾本之", "用甲骨文写信的人"],
      "sourceRanges": [
        {"blockId": "{{block:6}}", "fromGrapheme": null, "toGrapheme": null}
      ]
    },
    {
      "ordinal": 3,
      "summary": "这封信的信封地址不写曾本之工作的楚学院，而写“省博物馆背后，进东湖公园大门，过小梅岭、可竹轩，道路尽头俗称老鼠尾的半岛最前端先月亭前，周一下午四点十分独坐在此的曾本之先生亲启”；信封文字为打印机打印的标准楷体汉字，并非甲骨文。",
      "chronology": "与收信同时",
      "participants": ["曾本之", "用甲骨文写信的人"],
      "sourceRanges": [
        {"blockId": "{{block:7}}", "fromGrapheme": null, "toGrapheme": null},
        {"blockId": "{{block:8}}", "fromGrapheme": null, "toGrapheme": null}
      ]
    },
    {
      "ordinal": 4,
      "summary": "曾本之独坐先月亭，太阳将亭尖的阴影从他身体右边无声无息地移到左边。",
      "chronology": "接续叙述当下的独坐时刻",
      "participants": ["曾本之"],
      "sourceRanges": [
        {"blockId": "{{block:9}}", "fromGrapheme": null, "toGrapheme": null}
      ]
    },
    {
      "ordinal": 5,
      "summary": "有些无聊的曾本之捡起蚌壳随手一扔，正落在先月亭阴影顶尖；他忆起当年在随州擂鼓墩发掘曾侯乙大墓时周边村里小女孩用花布沙包玩跳房子的情形；连掷三次精准命中后，他改试打水漂，重量适中的蚌壳在水面弹起落下，划出美丽弧线推向湖心，最终悄无声息沉入湖底。",
      "chronology": "紧接独坐之后",
      "participants": ["曾本之"],
      "sourceRanges": [
        {"blockId": "{{block:10}}", "fromGrapheme": null, "toGrapheme": null}
      ]
    }
